SELECT EXISTS(
    SELECT 1
    FROM system_notification_recipients
    WHERE notification_id = #{notificationId}
      AND account_id = #{accountId}
)

SELECT EXISTS(
    SELECT 1
    FROM system_notification_recipients
    WHERE notification_id = #{notificationId}
      AND table_session_id = #{tableSessionId}
)

mapper.update:
UPDATE system_notification_recipients
SET status = 'READ', read_at = COALESCE(read_at, #{readAt})
WHERE notification_id = #{notificationId}
  AND account_id = #{accountId}

UPDATE system_notification_recipients
SET status = 'READ', read_at = COALESCE(read_at, #{readAt})
WHERE notification_id = #{notificationId}
  AND table_session_id = #{tableSessionId}

UPDATE system_notification_recipients
SET status = 'READ', read_at = #{readAt}
WHERE account_id = #{accountId}
  AND status = 'UNREAD'

UPDATE system_notification_recipients
SET status = 'READ', read_at = #{readAt}
WHERE table_session_id = #{tableSessionId}
  AND status = 'UNREAD'

